قطرات ماء تسقط من السحاب؛ شمس — نجم يمد الأرض بالضوء والدفء؛ غيم — سحب نراها في السماء. اقرأ الكلمات مع معلمك أو أحد أفراد أسرتك، ويمكنك رسم صورة من ابتكارك أمام كل كلمة. هذا إثراء مستقل ولا يفترض نقل صور الكتاب أو اعتماد مطابقة صفحة الوزارة.","sourceKind":"independent original flashcards, not Ministry images","topic":"الطقس","items":[{"sentence":"___: سحب نراها في السماء.","options":["مطر","غيم","شمس"]}]},"answer":{"answers":["غيم"]}},{"lessonId":"db6d40b0-d41f-439e-9be4-acd74fcb057f","page":108,"activity_order":5,"activity_type":"matching","title":"أربط الكلمة بمعناها","section":"practice","prompt":"اقرأ الكلمات الثلاث، ثم صِل كل كلمة بمعناها في قاموسي «الطقس».","content":{"origin":"DADYOOM_BH_G1_11_GLOSSARY_55_ORIGINAL_OPTIONAL_20261030","originalReference":"بطاقات ضاديوم الأصلية لقاموسي «الطقس»: مطر — قطرات ماء تسقط من السحاب؛ شمس — نجم يمد الأرض بالضوء والدفء؛ غيم — سحب نراها في السماء. اقرأ الكلمات مع معلمك أو أحد أفراد أسرتك، ويمكنك رسم صورة من ابتكارك أمام كل كلمة. هذا إثراء مستقل ولا يفترض نقل صور الكتاب أو اعتماد مطابقة صفحة الوزارة.","sourceKind":"independent original flashcards, not Ministry images","topic":"الطقس","left":["مطر","شمس","غيم"],"right":["نجم يمد الأرض بالضوء والدفء","سحب نراها في السماء","قطرات ماء تسقط من السحاب"]},"answer":{"pairs":[{"left":"مطر","right":"قطرات ماء تسقط من السحاب"},{"left":"شمس","right":"نجم يمد الأرض بالضوء والدفء"},{"left":"غيم","right":"سحب نراها في السماء"}]}},{"lessonId":"db6d40b0-d41f-439e-9be4-acd74fcb057f","page":108,"activity_order":6,"activity_type":"multiple_choice","title":"أستخدم المفردة في موقف","section":"practice","prompt":"تسقط قطرات ماء من السحب. ما اسمها؟","content":{"origin":"DADYOOM_BH_G1_11_GLOSSARY_55_ORIGINAL_OPTIONAL_20261030","originalReference":"بطاقات ضاديوم الأصلية لقاموسي «الطقس»: مطر — قطرات ماء تسقط من السحاب؛ شمس — نجم يمد الأرض بالضوء والدفء؛ غيم — سحب نراها في السماء. اقرأ الكلمات مع معلمك أو أحد أفراد أسرتك، ويمكنك رسم صورة من ابتكارك أمام كل كلمة. هذا إثراء مستقل ولا يفترض نقل صور الكتاب أو اعتماد مطابقة صفحة الوزارة.","sourceKind":"independent original flashcards, not Ministry images","topic":"الطقس","options":["غيم","شمس","مطر"]},"answer":{"correct":"مطر"}}]$glossary$::jsonb)
AS x("lessonId" text,page int,activity_order int,activity_type text,title text,section text,prompt text,content jsonb,answer jsonb);
DO $verify$
DECLARE real_lessons int; touched int; inserted int;
BEGIN
 IF (SELECT count(*) FROM pg_temp.bh_g1_glossary_55)<>55 OR
 (SELECT count(DISTINCT lesson_id) FROM pg_temp.bh_g1_glossary_55)<>11 OR
 (SELECT count(DISTINCT(lesson_id,activity_order)) FROM pg_temp.bh_g1_glossary_55)<>55 OR
 EXISTS(SELECT 1 FROM pg_temp.bh_g1_glossary_55 WHERE
 length(content->>'originalReference')<160 OR content ? 'correct' OR content ? 'answer' OR answer IS NULL)
 THEN RAISE EXCEPTION 'Invalid 11 individual source-grounded original glossary packs'; END IF;
 WITH c AS (
 SELECT l.id,l.content,l.source_page_start,co.code,g.grade_number,
 (SELECT count(*) FROM public.lesson_activities a WHERE a.lesson_id=l.id AND a.is_published) published_activities,
 (SELECT max(a.activity_order) FROM public.lesson_activities a WHERE a.lesson_id=l.id) max_order,
 EXISTS(SELECT 1 FROM public.student_lesson_progress slp WHERE slp.lesson_id=l.id) has_progress,
 EXISTS(SELECT 1 FROM public.lesson_activity_attempts at JOIN public.lesson_activities a ON a.id=at.activity_id WHERE a.lesson_id=l.id) has_activity_attempts,
 EXISTS(SELECT 1 FROM public.question_attempts at JOIN public.questions q ON q.id=at.question_id WHERE q.lesson_id=l.id) has_question_attempts
 FROM public.lessons l JOIN public.units u ON u.id=l.unit_id JOIN public.grades g ON g.id=u.grade_id
 JOIN public.curricula cu ON cu.id=g.curriculum_id JOIN public.countries co ON co.id=cu.country_id
 WHERE l.status='published' AND l.title='قاموسي المصور' AND g.grade_number=1 AND co.code='BH')
 SELECT COUNT(DISTINCT c.id) INTO real_lessons
 FROM c JOIN pg_temp.bh_g1_glossary_55 t ON t.lesson_id=c.id AND t.source_page=c.source_page_start
 WHERE c.published_activities=1 AND c.max_order=1 AND c.content LIKE '%قاموسي%'
 AND NOT c.has_progress AND NOT c.has_activity_attempts AND NOT c.has_question_attempts;
 IF real_lessons<>11 THEN RAISE EXCEPTION 'Scope or learner-history drift: % / 11 unique glossary lessons',real_lessons; END IF;
 IF EXISTS(SELECT 1 FROM public.lesson_activities WHERE content->>'origin'='DADYOOM_BH_G1_11_GLOSSARY_55_ORIGINAL_OPTIONAL_20261030')
 THEN RAISE EXCEPTION 'Original glossary batch already inserted'; END IF;
 INSERT INTO public.lesson_activities
 (lesson_id,title,activity_type,instructions,content,activity_order,points,is_published,section,prompt,answer,is_required)
 SELECT l.id,t.title,t.activity_type,'اقرأ بطاقة قاموس ضاديوم الأصلية ثم نفّذ التدريب المناسب لك. نشاط إثرائي مستقل غير وزاري.',
 t.content,t.activity_order,5,true,t.section,t.prompt,t.answer,false
 FROM public.lessons l JOIN public.units u ON u.id=l.unit_id JOIN public.grades g ON g.id=u.grade_id
 JOIN public.curricula cu ON cu.id=g.curriculum_id JOIN public.countries co ON co.id=cu.country_id
 JOIN pg_temp.bh_g1_glossary_55 t ON t.lesson_id=l.id AND t.source_page=l.source_page_start
 WHERE l.status='published' AND l.title='قاموسي المصور' AND g.grade_number=1 AND co.code='BH'
 AND l.content LIKE '%قاموسي%'
 AND NOT EXISTS(SELECT 1 FROM public.student_lesson_progress p WHERE p.lesson_id=l.id)
 AND NOT EXISTS(SELECT 1 FROM public.lesson_activity_attempts at JOIN public.lesson_activities a ON a.id=at.activity_id WHERE a.lesson_id=l.id)
 AND NOT EXISTS(SELECT 1 FROM public.question_attempts at JOIN public.questions q ON q.id=at.question_id WHERE q.lesson_id=l.id);
 GET DIAGNOSTICS inserted=ROW_COUNT;
 IF inserted<>55 THEN RAISE EXCEPTION 'Atomic rollback: inserted % not 55',inserted; END IF;
 SELECT COUNT(DISTINCT lesson_id) INTO touched FROM public.lesson_activities WHERE content->>'origin'='DADYOOM_BH_G1_11_GLOSSARY_55_ORIGINAL_OPTIONAL_20261030';
 IF touched<>11 THEN RAISE EXCEPTION 'Atomic rollback: only % / 11 target lessons',touched; END IF;
 RAISE NOTICE 'DADYOOM_BH_G1_ORIGINAL_GLOSSARY_ACTIVITIES=%',inserted;
END $verify$;
COMMIT;
